import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    idx = 0
    try:
        n1 = int(input_data[idx])
        idx += 1
        s1 = []
        for _ in range(n1):
            s1.append(input_data[idx])
            idx += 1

        n2 = int(input_data[idx])
        idx += 1
        s2 = []
        for _ in range(n2):
            s2.append(input_data[idx])
            idx += 1
    except IndexError:
        return

    count = 0
    for s in s2:
        found = False
        for t in s1:
            if t.startswith(s) or t.endswith(s):
                found = True
                break
        if found:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
